import React from 'react';

const Footer = () => {
    return (
        // <footer className="w-full py-4 px-margin-mobile md:px-margin-desktop flex flex-col md:flex-row justify-between items-center gap-4 bg-black border-t border-outline-variant dark:border-outline">
        //     <div className="flex flex-col items-center md:items-start gap-4">
        //         <span className="font-label-md text-label-md font-bold text-white">TheEntrance</span>
        //         <p className="font-body-sm text-body-sm text-gray-300">© 2026 The Entrance Solutions. All rights reserved.</p>
        //     </div>
        //     <div className="flex flex-wrap justify-center gap-6">
        //         <a className="font-body-sm text-body-sm text-gray-300 hover:text-white transition-colors cursor-pointer" href="/">Privacy Policy</a>
        //         <a className="font-body-sm text-body-sm text-gray-300 hover:text-white transition-colors cursor-pointer" href="/">Terms of Service</a>
        //         <a className="font-body-sm text-body-sm text-gray-300 hover:text-white transition-colors cursor-pointer" href="/">Security</a>
        //         <a className="font-body-sm text-body-sm text-gray-300 hover:text-white transition-colors cursor-pointer" href="/">Help Center</a>
        //     </div>
        // </footer>
        <footer class="bg-tertiary text-on-tertiary">
<div class="w-full py-12 px-margin-desktop max-w-container-max mx-auto flex flex-col md:flex-row justify-between items-center gap-base">
<div class="flex flex-col gap-4">
<span class="font-headline-md text-headline-md font-bold text-on-tertiary">NexusTrade</span>
<p class="font-body-sm text-body-sm text-on-tertiary-container max-w-xs">Leading the charge in enterprise-grade server technology and global supply chain solutions.</p>
</div>
<div class="flex flex-wrap gap-8">
<a class="font-body-sm text-body-sm text-on-tertiary-container hover:text-on-tertiary transition-colors" href="#">Privacy Policy</a>
<a class="font-body-sm text-body-sm text-on-tertiary-container hover:text-on-tertiary transition-colors" href="#">Terms of Service</a>
<a class="font-body-sm text-body-sm text-on-tertiary-container hover:text-on-tertiary transition-colors" href="#">Security</a>
<a class="font-body-sm text-body-sm text-on-tertiary-container hover:text-on-tertiary transition-colors" href="#">Compliance</a>
<a class="font-body-sm text-body-sm text-on-tertiary-container hover:text-on-tertiary transition-colors" href="#">Sitemap</a>
</div>
</div>
<div class="w-full border-t border-tertiary-fixed-dim/10 py-6 px-margin-desktop max-w-container-max mx-auto text-center">
<p class="font-body-sm text-body-sm text-on-tertiary-container">© 2024 NexusTrade Enterprise Solutions. All rights reserved.</p>
</div>
</footer>
    );
};

export default Footer;
